-- 6.x: spawnMask has one bit per Difficulty.dbc id (TC 6.x) and needs 64 bits.
-- The 4.3.4 rows used the legacy spawn modes (bit 0 normal / 10 man, bit 1 heroic / 25 man, bit 2 10 man heroic,
-- bit 3 25 man heroic); every instance map that exists in the 4.3.4 client is converted to the difficulty ids the
-- map has in the 5.4.8 client (MapDifficulty.dbc, the 6.x ids). Maps added with 5.4.8 already use the new ids.
ALTER TABLE `creature` MODIFY `spawnMask` bigint unsigned NOT NULL DEFAULT '1';
ALTER TABLE `gameobject` MODIFY `spawnMask` bigint unsigned NOT NULL DEFAULT '1';
UPDATE `creature` SET `spawnMask` = IF(`spawnMask` & 1, 2, 0) | IF(`spawnMask` & 2, 4, 0) WHERE `map` = 33 AND `spawnMask` <= 15;
UPDATE `gameobject` SET `spawnMask` = IF(`spawnMask` & 1, 2, 0) | IF(`spawnMask` & 2, 4, 0) WHERE `map` = 33 AND `spawnMask` <= 15;
