UPDATE `conditions` SET `ConditionValue1` =
    IF(`ConditionValue1` & 1, (1 << 0) | (1 << 1) | (1 << 3), 0) |
    IF(`ConditionValue1` & 2, (1 << 2) | (1 << 4), 0) |
    IF(`ConditionValue1` & 4, (1 << 5), 0) |
    IF(`ConditionValue1` & 8, (1 << 6), 0)
WHERE `ConditionTypeOrReference` = 19 AND `ConditionValue1` <= 15;
